WITH scored AS (SELECT *, LEAD(unit_price) OVER (PARTITION BY product_id ORDER BY unit_price, id) AS next_unit_price, LAG(unit_price) OVER (PARTITION BY product_id ORDER BY unit_price, id) AS prev_unit_price, LEAD(quantity) OVER (PARTITION BY product_id ORDER BY unit_price, id) AS next_quantity, LAG(quantity) OVER (PARTITION BY product_id ORDER BY unit_price, id) AS prev_quantity, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY unit_price, id) AS row_seq FROM order_items) SELECT order_id, CASE WHEN unit_price >= 330 THEN 'PREMIUM' ELSE 'STANDARD' END AS unit_price_tier, STDDEV_SAMP(quantity) AS quantity_stddev, COUNT(*) AS cnt, ROUND(AVG(prev_quantity), 2) AS avg_prev_quantity, BIT_AND(quantity) AS quantity_bit_and, ROUND(AVG(prev_quantity), 2) AS avg_prev_quantity_2 FROM scored GROUP BY CUBE (order_id, CASE WHEN unit_price >= 330 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY quantity_stddev DESC
